import java.util.*;

class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            graph.add(new ArrayList<>());
        }
        int[] indegree = new int[numCourses];
        for (int[] prerequisite : prerequisites) {
            int course = prerequisite[0];
            int before = prerequisite[1];
            graph.get(before).add(course);
            indegree[course]++;
        }

        Queue<Integer> ready = new ArrayDeque<>();
        for (int course = 0; course < numCourses; course++) {
            if (indegree[course] == 0) {
                ready.offer(course);
            }
        }

        int processed = 0;
        while (!ready.isEmpty()) {
            int course = ready.poll();
            processed++;
            for (int next : graph.get(course)) {
                indegree[next]--;
                if (indegree[next] == 0) {
                    ready.offer(next);
                }
            }
        }
        return processed == numCourses;
    }
}

import java.util.*;

class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            graph.add(new ArrayList<>());
        }
        for (int[] prerequisite : prerequisites) {
            graph.get(prerequisite[1]).add(prerequisite[0]);
        }

        int[] state = new int[numCourses];
        for (int course = 0; course < numCourses; course++) {
            if (!isAcyclic(graph, state, course)) {
                return false;
            }
        }
        return true;
    }

    private boolean isAcyclic(List<List<Integer>> graph, int[] state, int course) {
        if (state[course] == 1) {
            return false;
        }
        if (state[course] == 2) {
            return true;
        }
        state[course] = 1;
        for (int next : graph.get(course)) {
            if (!isAcyclic(graph, state, next)) {
                return false;
            }
        }
        state[course] = 2;
        return true;
    }
}

import java.util.*;

class Solution {
    private List<List<Integer>> graph;
    private int[] index;
    private int[] low;
    private boolean[] onStack;
    private Deque<Integer> stack;
    private int time;
    private boolean hasCycle;

    public boolean canFinish(int numCourses, int[][] prerequisites) {
        graph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            graph.add(new ArrayList<>());
        }
        for (int[] prerequisite : prerequisites) {
            graph.get(prerequisite[1]).add(prerequisite[0]);
        }

        index = new int[numCourses];
        low = new int[numCourses];
        onStack = new boolean[numCourses];
        stack = new ArrayDeque<>();
        Arrays.fill(index, -1);

        for (int course = 0; course < numCourses && !hasCycle; course++) {
            if (index[course] == -1) {
                strongConnect(course);
            }
        }
        return !hasCycle;
    }

    private void strongConnect(int node) {
        index[node] = time;
        low[node] = time;
        time++;
        stack.push(node);
        onStack[node] = true;

        for (int next : graph.get(node)) {
            if (next == node) {
                hasCycle = true;
            }
            if (index[next] == -1) {
                strongConnect(next);
                low[node] = Math.min(low[node], low[next]);
            } else if (onStack[next]) {
                low[node] = Math.min(low[node], index[next]);
            }
        }

        if (low[node] == index[node]) {
            int componentSize = 0;
            int current;
            do {
                current = stack.pop();
                onStack[current] = false;
                componentSize++;
            } while (current != node);
            if (componentSize > 1) {
                hasCycle = true;
            }
        }
    }
}

import java.util.*;

class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        List<List<Integer>> reverseGraph = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            graph.add(new ArrayList<>());
            reverseGraph.add(new ArrayList<>());
        }
        boolean hasSelfLoop = false;
        for (int[] prerequisite : prerequisites) {
            int course = prerequisite[0];
            int before = prerequisite[1];
            if (course == before) {
                hasSelfLoop = true;
            }
            graph.get(before).add(course);
            reverseGraph.get(course).add(before);
        }
        if (hasSelfLoop) {
            return false;
        }

        boolean[] visited = new boolean[numCourses];
        List<Integer> order = new ArrayList<>();
        for (int course = 0; course < numCourses; course++) {
            if (!visited[course]) {
                fillOrder(graph, visited, order, course);
            }
        }

        Arrays.fill(visited, false);
        for (int i = order.size() - 1; i >= 0; i--) {
            int course = order.get(i);
            if (!visited[course]) {
                int componentSize = markComponent(reverseGraph, visited, course);
                if (componentSize > 1) {
                    return false;
                }
            }
        }
        return true;
    }

    private void fillOrder(List<List<Integer>> graph, boolean[] visited, List<Integer> order, int course) {
        visited[course] = true;
        for (int next : graph.get(course)) {
            if (!visited[next]) {
                fillOrder(graph, visited, order, next);
            }
        }
        order.add(course);
    }

    private int markComponent(List<List<Integer>> reverseGraph, boolean[] visited, int course) {
        visited[course] = true;
        int size = 1;
        for (int next : reverseGraph.get(course)) {
            if (!visited[next]) {
                size += markComponent(reverseGraph, visited, next);
            }
        }
        return size;
    }
}
